create table if not exists public."Hot_Stamping_calibrations" (id uuid primary key default gen_random_uuid(), material text, foil text, machine text, temperature numeric, pressure numeric, dwell_time numeric, comments text, created_at timestamptz default now()); create table if not exists public.hot_machines (id uuid primary key default gen_random_uuid(), name text unique not null, temperature_max numeric, pressure_max numeric, dwell_time_max numeric, site text, created_at timestamptz default now()); alter table public."Hot_Stamping_calibrations" enable row level security; alter table public.hot_machines enable row level security; create policy if not exists hot_calib_read on public."Hot_Stamping_calibrations" for select to anon using (true); create policy if not exists hot_calib_insert on public."Hot_Stamping_calibrations" for insert to anon with check (true); create policy if not exists hot_machines_read on public.hot_machines for select to anon using (true); create policy if not exists hot_machines_insert on public.hot_machines for insert to anon with check (true); grant usage on schema public to anon, authenticated; grant select,insert on public."Hot_Stamping_calibrations", public.hot_machines to anon, authenticated; notify pgrst, 'reload schema';